(function(){'use strict';var sheet=document.getElementById('sheet');if(!sheet)return;var guides=null,raf=0;function ensure(){if(guides&&guides.isConnected)return guides;guides=document.createElement('div');guides.className='welog-align-guides';guides.hidden=true;guides.innerHTML='<i class="welog-align-guide v"></i><i class="welog-align-guide h"></i><span class="welog-align-guide-label"></span>';sheet.appendChild(guides);return guides}function selectedRect(){var box=sheet.querySelector('.welog-layout-box');if(!box||!document.body.classList.contains('welog-layout-editing'))return null;return box.getBoundingClientRect()}function draw(){raf=0;var g=ensure(),dragging=document.body.classList.contains('welog-layout-dragging'),r=selectedRect();if(!dragging||!r){g.hidden=true;return}var sr=sheet.getBoundingClientRect(),v=g.querySelector('.v'),h=g.querySelector('.h'),lab=g.querySelector('.welog-align-guide-label'),cx=(sr.left+sr.right)/2,cy=(sr.top+sr.bottom)/2,px=(r.left+r.right)/2,py=(r.top+r.bottom)/2,dx=Math.abs(px-cx),dy=Math.abs(py-cy),nearX=dx<=18,nearY=dy<=18,snapX=dx<=5,snapY=dy<=5;g.hidden=false;v.style.left=((cx-sr.left)/(sr.width/(sheet.offsetWidth||sr.width||1)))+'px';h.style.top=((cy-sr.top)/(sr.height/(sheet.offsetHeight||sr.height||1)))+'px';v.classList.toggle('show',nearX);h.classList.toggle('show',nearY);v.classList.toggle('snap',snapX);h.classList.toggle('snap',snapY);lab.classList.remove('show');if(snapX||snapY){lab.textContent=snapX&&snapY?'가운데 정렬':'가운데 '+(snapX?'세로선':'가로선');lab.style.left='50%';lab.style.top='50%';lab.style.transform='translate(8px,8px)';lab.classList.add('show')}}function schedule(){if(!raf)raf=requestAnimationFrame(draw)}new MutationObserver(schedule).observe(document.body,{attributes:true,attributeFilter:['class'],subtree:true});new MutationObserver(schedule).observe(sheet,{attributes:true,attributeFilter:['style','class'],subtree:true});window.addEventListener('pointermove',schedule,true);window.addEventListener('pointerup',function(){schedule();setTimeout(schedule,30)},true);window.addEventListener('resize',schedule);ensure();})();